-- A2. Read-only inspection before the transaction.
SELECT DATABASE() AS target_schema, VERSION() AS mysql_version, @@SESSION.foreign_key_checks AS fk_enabled,
       @@max_allowed_packet AS max_allowed_packet, JSON_VALID(@e_patches) AS payload_json_valid,
       JSON_LENGTH(@e_patches) AS payload_tables_must_be_52;
SELECT tmplt_id, mdl_spt_cd, tmplt_ver_no, tmplt_stat_cd, aply_bgn_dtm, del_yn, tmplt_expn
FROM tmd_mdl_inpttmpltm WHERE mdl_spt_cd = @e_model ORDER BY tmplt_ver_no;

-- A3. Lock the model's roots (new version slot included) and template7's hierarchy for the whole transaction.
SET TRANSACTION ISOLATION LEVEL SERIALIZABLE;
START TRANSACTION;
SELECT tmplt_id FROM tmd_mdl_inpttmpltm WHERE mdl_spt_cd = @e_model FOR UPDATE;
SELECT inpt_file_id FROM tmd_mdl_inptfiled WHERE tmplt_id = @e_source FOR SHARE;
SELECT s.inpt_sht_id FROM tmd_mdl_inptshtd s JOIN tmd_mdl_inptfiled f USING(inpt_file_id) WHERE f.tmplt_id = @e_source FOR SHARE;
SELECT b.inpt_tbl_id FROM tmd_mdl_inpttbld b JOIN tmd_mdl_inptshtd s USING(inpt_sht_id)
JOIN tmd_mdl_inptfiled f USING(inpt_file_id) WHERE f.tmplt_id = @e_source FOR SHARE;
SELECT m.mod_scop_id FROM tmd_mdl_inptmodscopd m JOIN tmd_mdl_inpttbld b USING(inpt_tbl_id)
JOIN tmd_mdl_inptshtd s USING(inpt_sht_id) JOIN tmd_mdl_inptfiled f USING(inpt_file_id) WHERE f.tmplt_id = @e_source FOR SHARE;
SELECT case_id FROM tmd_mdl_scnrcasetmpltd WHERE tmplt_id = @e_source FOR SHARE;

-- Digest of template7's whole hierarchy; recomputed after the writes to prove template7 stayed unchanged.
SET @e_src_before = (SELECT SHA2(GROUP_CONCAT(SHA2(CONCAT_WS(CHAR(31), f.mdl_file_cd, f.file_nm, f.file_ord, f.file_type_cd,
  IFNULL(f.file_strt_hash_val, ''), f.del_yn, s.sht_nm, s.sht_ord, s.sht_stat_cd, s.del_yn, b.inpt_tbl_id, b.inpt_tbl_nm, b.tbl_ord,
  b.tbl_bgn_row_no, b.tbl_end_row_no, b.tbl_bgn_col_no, b.tbl_end_col_no, b.hdr_bgn_row_no, b.hdr_end_row_no, b.data_bgn_row_no,
  b.row_add_psbl_yn, b.col_add_psbl_yn, IFNULL(b.inpt_tbl_expn, ''), b.qry_json, b.mod_dtm, b.del_yn), 256)
  ORDER BY b.inpt_tbl_id SEPARATOR ','), 256)
 FROM tmd_mdl_inptfiled f JOIN tmd_mdl_inptshtd s USING(inpt_file_id) JOIN tmd_mdl_inpttbld b USING(inpt_sht_id)
 WHERE f.tmplt_id = @e_source);
SET @e_links_before = (SELECT COUNT(*) FROM tmd_mdl_scnrcasetmpltd WHERE tmplt_id = @e_source);

-- A4. Guards. Every patched table must still equal the analysed template7 definition (+ an uploadValidation object).
SET @e_patch_matches = (SELECT COUNT(*) FROM JSON_TABLE(@e_patches, '$[*]' COLUMNS(
   role VARCHAR(20) PATH '$.role', sheet VARCHAR(150) PATH '$.sheet', name VARCHAR(100) PATH '$.name',
   ord INT PATH '$.geometry.ord', br INT PATH '$.geometry.br', er INT PATH '$.geometry.er', bc INT PATH '$.geometry.bc',
   ec INT PATH '$.geometry.ec', hr INT PATH '$.geometry.hr', he INT PATH '$.geometry.he', dr INT PATH '$.geometry.dr',
   ra CHAR(1) PATH '$.geometry.ra', ca CHAR(1) PATH '$.geometry.ca', baseline JSON PATH '$.baseline')) x
 JOIN tmd_mdl_inptfiled f ON f.tmplt_id = @e_source AND BINARY f.mdl_file_cd = BINARY x.role AND f.del_yn = 'N'
 JOIN tmd_mdl_inptshtd s ON s.inpt_file_id = f.inpt_file_id AND BINARY s.sht_nm = BINARY x.sheet
   AND s.sht_stat_cd = 'VISIBLE' AND s.del_yn = 'N'
 JOIN tmd_mdl_inpttbld b ON b.inpt_sht_id = s.inpt_sht_id AND BINARY b.inpt_tbl_nm = BINARY x.name AND b.del_yn = 'N'
 WHERE b.tbl_ord = x.ord AND b.tbl_bgn_row_no = x.br AND b.tbl_end_row_no = x.er AND b.tbl_bgn_col_no = x.bc
   AND b.tbl_end_col_no = x.ec AND b.hdr_bgn_row_no = x.hr AND b.hdr_end_row_no = x.he AND b.data_bgn_row_no = x.dr
   AND b.row_add_psbl_yn = x.ra AND b.col_add_psbl_yn = x.ca AND JSON_VALID(b.qry_json) = 1
   AND JSON_TYPE(JSON_EXTRACT(b.qry_json, '$.uploadValidation')) = 'OBJECT'
   AND JSON_REMOVE(CAST(b.qry_json AS JSON), '$.uploadValidation') = x.baseline);
SET @e_payload_keys = (SELECT COUNT(DISTINCT CONCAT(role, CHAR(31), sheet, CHAR(31), name)) FROM JSON_TABLE(@e_patches, '$[*]'
  COLUMNS(role VARCHAR(20) PATH '$.role', sheet VARCHAR(150) PATH '$.sheet', name VARCHAR(100) PATH '$.name')) x);
SET @e_payload_scopes = (SELECT COUNT(*) FROM JSON_TABLE(@e_patches, '$[*]' COLUMNS(NESTED PATH '$.scopes[*]'
  COLUMNS(r1 INT PATH '$.startRow'))) x WHERE x.r1 IS NOT NULL);
SET @e_ok = IF(BINARY DATABASE() = BINARY @e_schema AND @@SESSION.foreign_key_checks = 1
 AND CHAR_LENGTH(TRIM(@e_actor)) BETWEEN 1 AND 50
 AND @e_version BETWEEN 2 AND 65535 AND @e_version = FLOOR(@e_version)
 AND JSON_VALID(@e_patches) = 1 AND JSON_LENGTH(@e_patches) = 52 AND @e_payload_keys = 52 AND @e_payload_scopes = 126
 AND (SELECT COUNT(*) FROM tmd_mdl_inpttmpltm WHERE tmplt_id = @e_source AND BINARY mdl_spt_cd = BINARY @e_model
      AND tmplt_ver_no = @e_source_version AND tmplt_stat_cd = 'ACTIVE' AND aply_bgn_dtm IS NOT NULL AND del_yn = 'N'
      AND BINARY tmplt_expn = BINARY @e_source_marker) = 1
 AND NOT EXISTS (SELECT 1 FROM tmd_mdl_inpttmpltm WHERE BINARY mdl_spt_cd = BINARY @e_model
      AND (tmplt_ver_no = @e_version OR BINARY tmplt_expn = BINARY @e_marker))
 AND (SELECT COUNT(*) FROM tmd_mdl_inptfiled WHERE tmplt_id = @e_source) = 4
 AND (SELECT COUNT(*) FROM tmd_mdl_inptfiled WHERE tmplt_id = @e_source AND del_yn = 'N') = 4
 AND (SELECT COUNT(*) FROM tmd_mdl_inptshtd s JOIN tmd_mdl_inptfiled f USING(inpt_file_id)
      WHERE f.tmplt_id = @e_source AND s.del_yn = 'N') = 70
 AND (SELECT COUNT(*) FROM tmd_mdl_inptshtd s JOIN tmd_mdl_inptfiled f USING(inpt_file_id) WHERE f.tmplt_id = @e_source) = 70
 AND (SELECT COUNT(*) FROM tmd_mdl_inpttbld b JOIN tmd_mdl_inptshtd s USING(inpt_sht_id) JOIN tmd_mdl_inptfiled f USING(inpt_file_id)
      WHERE f.tmplt_id = @e_source AND b.del_yn = 'N' AND s.del_yn = 'N') = 92
 AND (SELECT COUNT(*) FROM tmd_mdl_inpttbld b JOIN tmd_mdl_inptshtd s USING(inpt_sht_id) JOIN tmd_mdl_inptfiled f USING(inpt_file_id)
      WHERE f.tmplt_id = @e_source) = 92
 AND NOT EXISTS (SELECT 1 FROM tmd_mdl_inptmodscopd m JOIN tmd_mdl_inpttbld b USING(inpt_tbl_id)
      JOIN tmd_mdl_inptshtd s USING(inpt_sht_id) JOIN tmd_mdl_inptfiled f USING(inpt_file_id) WHERE f.tmplt_id = @e_source)
 AND @e_patch_matches = 52 AND @e_src_before IS NOT NULL, 1, 0);
SELECT @e_patch_matches AS patched_baselines_must_be_52, @e_payload_scopes AS payload_scopes_must_be_126,
       @e_links_before AS template7_case_links, IF(@e_ok = 1, 'PRECHECK_OK', 'STOP_AND_ROLLBACK') AS decision;
-- STOP_AND_ROLLBACK: run ROLLBACK and stop. Writes below are all gated by @e_ok=1.

-- A5. New DRAFT root, then exact copies of the active children of template7.
INSERT INTO tmd_mdl_inpttmpltm
 (mdl_spt_cd, tmplt_ver_no, tmplt_ver_nm, tmplt_stat_cd, aply_bgn_dtm, tmplt_expn,
  crt_usr_logn_id, crt_dtm, mod_usr_logn_id, mod_dtm, del_yn)
SELECT @e_model, @e_version, @e_name, 'DRAFT', NULL, @e_marker, @e_actor, CURRENT_TIMESTAMP, @e_actor, CURRENT_TIMESTAMP, 'N'
FROM DUAL WHERE @e_ok = 1;
-- Read back the stored row by natural key + marker; do not rely on LAST_INSERT_ID or ROW_COUNT.
SET @e_new = (SELECT tmplt_id FROM tmd_mdl_inpttmpltm WHERE @e_ok = 1 AND BINARY mdl_spt_cd = BINARY @e_model
  AND tmplt_ver_no = @e_version AND BINARY tmplt_expn = BINARY @e_marker AND tmplt_stat_cd = 'DRAFT'
  AND aply_bgn_dtm IS NULL AND del_yn = 'N' AND crt_usr_logn_id = @e_actor);
INSERT INTO tmd_mdl_inptfiled
 (tmplt_id, mdl_file_cd, file_nm, file_ord, file_type_cd, file_strt_hash_val, crt_usr_logn_id, crt_dtm, mod_usr_logn_id, mod_dtm, del_yn)
SELECT @e_new, f.mdl_file_cd, f.file_nm, f.file_ord, f.file_type_cd, f.file_strt_hash_val,
       @e_actor, CURRENT_TIMESTAMP, @e_actor, CURRENT_TIMESTAMP, 'N'
FROM tmd_mdl_inptfiled f WHERE @e_ok = 1 AND @e_new IS NOT NULL AND f.tmplt_id = @e_source AND f.del_yn = 'N';
INSERT INTO tmd_mdl_inptshtd
 (inpt_file_id, sht_nm, sht_ord, sht_stat_cd, crt_usr_logn_id, crt_dtm, mod_usr_logn_id, mod_dtm, del_yn)
SELECT nf.inpt_file_id, s.sht_nm, s.sht_ord, s.sht_stat_cd, @e_actor, CURRENT_TIMESTAMP, @e_actor, CURRENT_TIMESTAMP, 'N'
FROM tmd_mdl_inptshtd s JOIN tmd_mdl_inptfiled sf ON sf.inpt_file_id = s.inpt_file_id AND sf.tmplt_id = @e_source
JOIN tmd_mdl_inptfiled nf ON nf.tmplt_id = @e_new AND BINARY nf.mdl_file_cd = BINARY sf.mdl_file_cd
WHERE @e_ok = 1 AND s.del_yn = 'N';
INSERT INTO tmd_mdl_inpttbld
 (inpt_sht_id, inpt_tbl_nm, tbl_ord, tbl_bgn_row_no, tbl_end_row_no, tbl_bgn_col_no, tbl_end_col_no,
  hdr_bgn_row_no, hdr_end_row_no, data_bgn_row_no, row_add_psbl_yn, col_add_psbl_yn, inpt_tbl_expn, qry_json,
  crt_usr_logn_id, crt_dtm, mod_usr_logn_id, mod_dtm, del_yn)
SELECT ns.inpt_sht_id, b.inpt_tbl_nm, b.tbl_ord, b.tbl_bgn_row_no, b.tbl_end_row_no, b.tbl_bgn_col_no, b.tbl_end_col_no,
       b.hdr_bgn_row_no, b.hdr_end_row_no, b.data_bgn_row_no, b.row_add_psbl_yn, b.col_add_psbl_yn, b.inpt_tbl_expn, b.qry_json,
       @e_actor, CURRENT_TIMESTAMP, @e_actor, CURRENT_TIMESTAMP, 'N'
FROM tmd_mdl_inpttbld b JOIN tmd_mdl_inptshtd ss ON ss.inpt_sht_id = b.inpt_sht_id
JOIN tmd_mdl_inptfiled sf ON sf.inpt_file_id = ss.inpt_file_id AND sf.tmplt_id = @e_source
JOIN tmd_mdl_inptfiled nf ON nf.tmplt_id = @e_new AND BINARY nf.mdl_file_cd = BINARY sf.mdl_file_cd
JOIN tmd_mdl_inptshtd ns ON ns.inpt_file_id = nf.inpt_file_id AND BINARY ns.sht_nm = BINARY ss.sht_nm
WHERE @e_ok = 1 AND b.del_yn = 'N';

-- A6. Replace only fields/capabilities(/columnCreation) of the 52 copied tables, then add their scopes.
UPDATE tmd_mdl_inpttbld b
JOIN tmd_mdl_inptshtd s ON s.inpt_sht_id = b.inpt_sht_id
JOIN tmd_mdl_inptfiled f ON f.inpt_file_id = s.inpt_file_id AND f.tmplt_id = @e_new
JOIN JSON_TABLE(@e_patches, '$[*]' COLUMNS(role VARCHAR(20) PATH '$.role', sheet VARCHAR(150) PATH '$.sheet',
  name VARCHAR(100) PATH '$.name', fields JSON PATH '$.fields', caps JSON PATH '$.capabilities',
  creation JSON PATH '$.columnCreation')) x
  ON BINARY f.mdl_file_cd = BINARY x.role AND BINARY s.sht_nm = BINARY x.sheet AND BINARY b.inpt_tbl_nm = BINARY x.name
SET b.qry_json = IF(x.creation IS NULL,
      JSON_SET(CAST(b.qry_json AS JSON), '$.fields', x.fields, '$.capabilities', x.caps),
      JSON_SET(CAST(b.qry_json AS JSON), '$.fields', x.fields, '$.capabilities', x.caps, '$.columnCreation', x.creation)),
    b.mod_usr_logn_id = @e_actor, b.mod_dtm = CURRENT_TIMESTAMP
WHERE @e_ok = 1 AND @e_new IS NOT NULL;
INSERT INTO tmd_mdl_inptmodscopd
 (inpt_tbl_id, mod_scop_ord, bgn_row_no, end_row_no, bgn_col_no, end_col_no,
  crt_usr_logn_id, crt_dtm, mod_usr_logn_id, mod_dtm, del_yn)
SELECT b.inpt_tbl_id, x.ord, x.r1, x.r2, x.c1, x.c2, @e_actor, CURRENT_TIMESTAMP, @e_actor, CURRENT_TIMESTAMP, 'N'
FROM JSON_TABLE(@e_patches, '$[*]' COLUMNS(role VARCHAR(20) PATH '$.role', sheet VARCHAR(150) PATH '$.sheet',
  name VARCHAR(100) PATH '$.name', NESTED PATH '$.scopes[*]' COLUMNS(ord INT PATH '$.ord',
  r1 INT PATH '$.startRow', r2 INT PATH '$.endRow', c1 INT PATH '$.startColumn', c2 INT PATH '$.endColumn'))) x
JOIN tmd_mdl_inptfiled f ON f.tmplt_id = @e_new AND BINARY f.mdl_file_cd = BINARY x.role
JOIN tmd_mdl_inptshtd s ON s.inpt_file_id = f.inpt_file_id AND BINARY s.sht_nm = BINARY x.sheet
JOIN tmd_mdl_inpttbld b ON b.inpt_sht_id = s.inpt_sht_id AND BINARY b.inpt_tbl_nm = BINARY x.name
WHERE @e_ok = 1 AND @e_new IS NOT NULL AND x.r1 IS NOT NULL;

-- A7. Verify stored rows (not driver ROW_COUNT): exact copies, exact patches, exact scopes, template7 untouched.
SET @e_src_after = (SELECT SHA2(GROUP_CONCAT(SHA2(CONCAT_WS(CHAR(31), f.mdl_file_cd, f.file_nm, f.file_ord, f.file_type_cd,
  IFNULL(f.file_strt_hash_val, ''), f.del_yn, s.sht_nm, s.sht_ord, s.sht_stat_cd, s.del_yn, b.inpt_tbl_id, b.inpt_tbl_nm, b.tbl_ord,
  b.tbl_bgn_row_no, b.tbl_end_row_no, b.tbl_bgn_col_no, b.tbl_end_col_no, b.hdr_bgn_row_no, b.hdr_end_row_no, b.data_bgn_row_no,
  b.row_add_psbl_yn, b.col_add_psbl_yn, IFNULL(b.inpt_tbl_expn, ''), b.qry_json, b.mod_dtm, b.del_yn), 256)
  ORDER BY b.inpt_tbl_id SEPARATOR ','), 256)
 FROM tmd_mdl_inptfiled f JOIN tmd_mdl_inptshtd s USING(inpt_file_id) JOIN tmd_mdl_inpttbld b USING(inpt_sht_id)
 WHERE f.tmplt_id = @e_source);
SET @e_files_copied = (SELECT COUNT(*) FROM tmd_mdl_inptfiled n JOIN tmd_mdl_inptfiled o
  ON o.tmplt_id = @e_source AND BINARY o.mdl_file_cd = BINARY n.mdl_file_cd AND BINARY o.file_nm = BINARY n.file_nm
  AND o.file_ord = n.file_ord AND o.file_type_cd = n.file_type_cd AND o.file_strt_hash_val <=> n.file_strt_hash_val
  WHERE n.tmplt_id = @e_new AND n.del_yn = 'N');
SET @e_sheets_copied = (SELECT COUNT(*) FROM tmd_mdl_inptshtd ns JOIN tmd_mdl_inptfiled nf ON nf.inpt_file_id = ns.inpt_file_id AND nf.tmplt_id = @e_new
  JOIN tmd_mdl_inptfiled sf ON sf.tmplt_id = @e_source AND BINARY sf.mdl_file_cd = BINARY nf.mdl_file_cd
  JOIN tmd_mdl_inptshtd ss ON ss.inpt_file_id = sf.inpt_file_id AND BINARY ss.sht_nm = BINARY ns.sht_nm
  WHERE ss.sht_ord = ns.sht_ord AND ss.sht_stat_cd = ns.sht_stat_cd AND ns.del_yn = 'N');
-- p = pairs of (new copy, template7 original) with identical names/geometry/description.
WITH p AS (SELECT nb.inpt_tbl_id AS new_id, nf.mdl_file_cd AS role, ns.sht_nm AS sheet, nb.inpt_tbl_nm AS name,
  nb.qry_json AS new_qry, ob.qry_json AS old_qry
 FROM tmd_mdl_inpttbld nb JOIN tmd_mdl_inptshtd ns ON ns.inpt_sht_id = nb.inpt_sht_id
 JOIN tmd_mdl_inptfiled nf ON nf.inpt_file_id = ns.inpt_file_id AND nf.tmplt_id = @e_new
 JOIN tmd_mdl_inptfiled sf ON sf.tmplt_id = @e_source AND BINARY sf.mdl_file_cd = BINARY nf.mdl_file_cd
 JOIN tmd_mdl_inptshtd ss ON ss.inpt_file_id = sf.inpt_file_id AND BINARY ss.sht_nm = BINARY ns.sht_nm
 JOIN tmd_mdl_inpttbld ob ON ob.inpt_sht_id = ss.inpt_sht_id AND BINARY ob.inpt_tbl_nm = BINARY nb.inpt_tbl_nm
 WHERE nb.del_yn = 'N' AND nb.tbl_ord = ob.tbl_ord AND nb.tbl_bgn_row_no = ob.tbl_bgn_row_no
  AND nb.tbl_end_row_no = ob.tbl_end_row_no AND nb.tbl_bgn_col_no = ob.tbl_bgn_col_no AND nb.tbl_end_col_no = ob.tbl_end_col_no
  AND nb.hdr_bgn_row_no = ob.hdr_bgn_row_no AND nb.hdr_end_row_no = ob.hdr_end_row_no AND nb.data_bgn_row_no = ob.data_bgn_row_no
  AND nb.row_add_psbl_yn = ob.row_add_psbl_yn AND nb.col_add_psbl_yn = ob.col_add_psbl_yn AND nb.inpt_tbl_expn <=> ob.inpt_tbl_expn),
x AS (SELECT * FROM JSON_TABLE(@e_patches, '$[*]' COLUMNS(role VARCHAR(20) PATH '$.role', sheet VARCHAR(150) PATH '$.sheet',
  name VARCHAR(100) PATH '$.name', fields JSON PATH '$.fields', caps JSON PATH '$.capabilities',
  creation JSON PATH '$.columnCreation')) j)
SELECT COUNT(*),
  SUM(x.role IS NULL AND CAST(p.new_qry AS JSON) = CAST(p.old_qry AS JSON)),
  SUM(x.role IS NOT NULL AND CAST(p.new_qry AS JSON) = IF(x.creation IS NULL,
      JSON_SET(CAST(p.old_qry AS JSON), '$.fields', x.fields, '$.capabilities', x.caps),
      JSON_SET(CAST(p.old_qry AS JSON), '$.fields', x.fields, '$.capabilities', x.caps, '$.columnCreation', x.creation)))
INTO @e_tables_paired, @e_unpatched_equal, @e_patched_equal
FROM p LEFT JOIN x ON BINARY x.role = BINARY p.role AND BINARY x.sheet = BINARY p.sheet AND BINARY x.name = BINARY p.name;
WITH p AS (SELECT nb.inpt_tbl_id AS new_id, nf.mdl_file_cd AS role, ns.sht_nm AS sheet, nb.inpt_tbl_nm AS name,
  nb.qry_json AS new_qry, ob.qry_json AS old_qry
 FROM tmd_mdl_inpttbld nb JOIN tmd_mdl_inptshtd ns ON ns.inpt_sht_id = nb.inpt_sht_id
 JOIN tmd_mdl_inptfiled nf ON nf.inpt_file_id = ns.inpt_file_id AND nf.tmplt_id = @e_new
 JOIN tmd_mdl_inptfiled sf ON sf.tmplt_id = @e_source AND BINARY sf.mdl_file_cd = BINARY nf.mdl_file_cd
 JOIN tmd_mdl_inptshtd ss ON ss.inpt_file_id = sf.inpt_file_id AND BINARY ss.sht_nm = BINARY ns.sht_nm
 JOIN tmd_mdl_inpttbld ob ON ob.inpt_sht_id = ss.inpt_sht_id AND BINARY ob.inpt_tbl_nm = BINARY nb.inpt_tbl_nm
 WHERE nb.del_yn = 'N' AND nb.tbl_ord = ob.tbl_ord AND nb.tbl_bgn_row_no = ob.tbl_bgn_row_no
  AND nb.tbl_end_row_no = ob.tbl_end_row_no AND nb.tbl_bgn_col_no = ob.tbl_bgn_col_no AND nb.tbl_end_col_no = ob.tbl_end_col_no
  AND nb.hdr_bgn_row_no = ob.hdr_bgn_row_no AND nb.hdr_end_row_no = ob.hdr_end_row_no AND nb.data_bgn_row_no = ob.data_bgn_row_no
  AND nb.row_add_psbl_yn = ob.row_add_psbl_yn AND nb.col_add_psbl_yn = ob.col_add_psbl_yn AND nb.inpt_tbl_expn <=> ob.inpt_tbl_expn)
SELECT COUNT(*) INTO @e_scopes_equal FROM JSON_TABLE(@e_patches, '$[*]' COLUMNS(role VARCHAR(20) PATH '$.role',
  sheet VARCHAR(150) PATH '$.sheet', name VARCHAR(100) PATH '$.name', NESTED PATH '$.scopes[*]' COLUMNS(ord INT PATH '$.ord',
  r1 INT PATH '$.startRow', r2 INT PATH '$.endRow', c1 INT PATH '$.startColumn', c2 INT PATH '$.endColumn'))) x
 JOIN p ON BINARY x.role = BINARY p.role AND BINARY x.sheet = BINARY p.sheet AND BINARY x.name = BINARY p.name
 JOIN tmd_mdl_inptmodscopd m ON m.inpt_tbl_id = p.new_id AND m.mod_scop_ord = x.ord AND m.bgn_row_no = x.r1
  AND m.end_row_no = x.r2 AND m.bgn_col_no = x.c1 AND m.end_col_no = x.c2 AND m.del_yn = 'N'
 WHERE x.r1 IS NOT NULL;
SET @e_scopes_total = (SELECT COUNT(*) FROM tmd_mdl_inptmodscopd m JOIN tmd_mdl_inpttbld b USING(inpt_tbl_id)
  JOIN tmd_mdl_inptshtd s USING(inpt_sht_id) JOIN tmd_mdl_inptfiled f USING(inpt_file_id) WHERE f.tmplt_id = @e_new);
-- The digest binds the exact stored file/sheet/table/scope hierarchy to this DRAFT.
SET @e_catalog_digest = (
  SELECT SHA2(GROUP_CONCAT(SHA2(payload, 256) ORDER BY record_kind, record_id SEPARATOR ','), 256)
  FROM (
    SELECT 'F' AS record_kind, f.inpt_file_id AS record_id,
      CAST(JSON_ARRAY('F', f.inpt_file_id, f.tmplt_id, f.mdl_file_cd, f.file_nm, f.file_ord,
        f.file_type_cd, f.file_strt_hash_val, f.del_yn) AS CHAR) AS payload
    FROM tmd_mdl_inptfiled f WHERE f.tmplt_id = @e_new
    UNION ALL
    SELECT 'S', s.inpt_sht_id,
      CAST(JSON_ARRAY('S', s.inpt_sht_id, s.inpt_file_id, s.sht_nm, s.sht_ord, s.sht_stat_cd, s.del_yn) AS CHAR)
    FROM tmd_mdl_inptshtd s JOIN tmd_mdl_inptfiled f USING(inpt_file_id) WHERE f.tmplt_id = @e_new
    UNION ALL
    SELECT 'T', b.inpt_tbl_id,
      CAST(JSON_ARRAY('T', b.inpt_tbl_id, b.inpt_sht_id, b.inpt_tbl_nm, b.tbl_ord,
        b.tbl_bgn_row_no, b.tbl_end_row_no, b.tbl_bgn_col_no, b.tbl_end_col_no,
        b.hdr_bgn_row_no, b.hdr_end_row_no, b.data_bgn_row_no, b.row_add_psbl_yn,
        b.col_add_psbl_yn, b.inpt_tbl_expn, b.qry_json, b.del_yn) AS CHAR)
    FROM tmd_mdl_inpttbld b JOIN tmd_mdl_inptshtd s USING(inpt_sht_id)
      JOIN tmd_mdl_inptfiled f USING(inpt_file_id) WHERE f.tmplt_id = @e_new
    UNION ALL
    SELECT 'M', m.mod_scop_id,
      CAST(JSON_ARRAY('M', m.mod_scop_id, m.inpt_tbl_id, m.mod_scop_ord, m.bgn_row_no,
        m.end_row_no, m.bgn_col_no, m.end_col_no, m.del_yn) AS CHAR)
    FROM tmd_mdl_inptmodscopd m JOIN tmd_mdl_inpttbld b USING(inpt_tbl_id)
      JOIN tmd_mdl_inptshtd s USING(inpt_sht_id) JOIN tmd_mdl_inptfiled f USING(inpt_file_id)
    WHERE f.tmplt_id = @e_new
  ) hierarchy
);
UPDATE tmd_mdl_inpttmpltm SET tmplt_expn = CONCAT(@e_marker, '; digest=', @e_catalog_digest)
WHERE @e_ok = 1 AND @e_new IS NOT NULL AND @e_catalog_digest IS NOT NULL
  AND tmplt_id = @e_new AND BINARY tmplt_expn = BINARY @e_marker AND tmplt_stat_cd = 'DRAFT';
SET @e_verified = IF(@e_ok = 1 AND @e_new IS NOT NULL
 AND (SELECT COUNT(*) FROM tmd_mdl_inpttmpltm WHERE tmplt_id = @e_new
      AND BINARY tmplt_expn = BINARY CONCAT(@e_marker, '; digest=', @e_catalog_digest)) = 1
 AND (SELECT COUNT(*) FROM tmd_mdl_inpttmpltm WHERE BINARY mdl_spt_cd = BINARY @e_model AND tmplt_ver_no = @e_version) = 1
 AND (SELECT COUNT(*) FROM tmd_mdl_inptfiled WHERE tmplt_id = @e_new) = 4 AND @e_files_copied = 4
 AND (SELECT COUNT(*) FROM tmd_mdl_inptshtd s JOIN tmd_mdl_inptfiled f USING(inpt_file_id) WHERE f.tmplt_id = @e_new) = 70
 AND @e_sheets_copied = 70
 AND (SELECT COUNT(*) FROM tmd_mdl_inpttbld b JOIN tmd_mdl_inptshtd s USING(inpt_sht_id) JOIN tmd_mdl_inptfiled f USING(inpt_file_id)
      WHERE f.tmplt_id = @e_new) = 92
 AND @e_tables_paired = 92 AND @e_unpatched_equal = 40 AND @e_patched_equal = 52
 AND @e_scopes_equal = 126 AND @e_scopes_total = 126
 AND @e_src_after = @e_src_before
 AND (SELECT COUNT(*) FROM tmd_mdl_scnrcasetmpltd WHERE tmplt_id = @e_source) = @e_links_before
 AND NOT EXISTS (SELECT 1 FROM tmd_mdl_scnrcasetmpltd WHERE tmplt_id = @e_new)
 AND (SELECT COUNT(*) FROM tmd_mdl_inpttmpltm WHERE tmplt_id = @e_source AND tmplt_stat_cd = 'ACTIVE') = 1, 1, 0);
SELECT @e_new AS new_tmplt_id, @e_tables_paired AS tables_must_be_92, @e_unpatched_equal AS unpatched_must_be_40,
       @e_patched_equal AS patched_must_be_52, @e_scopes_equal AS scopes_must_be_126,
       IF(@e_src_after = @e_src_before, 'UNCHANGED', 'CHANGED') AS template7_hierarchy,
       IF(@e_verified = 1, 'VERIFIED_UNPUBLISHED', 'STOP_AND_ROLLBACK') AS decision;
-- Review readout: one row per changed table of the new DRAFT.
WITH p AS (SELECT nb.inpt_tbl_id AS new_id, nf.mdl_file_cd AS role, ns.sht_nm AS sheet, nb.inpt_tbl_nm AS name,
  nb.qry_json AS new_qry, ob.qry_json AS old_qry
 FROM tmd_mdl_inpttbld nb JOIN tmd_mdl_inptshtd ns ON ns.inpt_sht_id = nb.inpt_sht_id
 JOIN tmd_mdl_inptfiled nf ON nf.inpt_file_id = ns.inpt_file_id AND nf.tmplt_id = @e_new
 JOIN tmd_mdl_inptfiled sf ON sf.tmplt_id = @e_source AND BINARY sf.mdl_file_cd = BINARY nf.mdl_file_cd
 JOIN tmd_mdl_inptshtd ss ON ss.inpt_file_id = sf.inpt_file_id AND BINARY ss.sht_nm = BINARY ns.sht_nm
 JOIN tmd_mdl_inpttbld ob ON ob.inpt_sht_id = ss.inpt_sht_id AND BINARY ob.inpt_tbl_nm = BINARY nb.inpt_tbl_nm
 WHERE nb.del_yn = 'N' AND nb.tbl_ord = ob.tbl_ord AND nb.tbl_bgn_row_no = ob.tbl_bgn_row_no
  AND nb.tbl_end_row_no = ob.tbl_end_row_no AND nb.tbl_bgn_col_no = ob.tbl_bgn_col_no AND nb.tbl_end_col_no = ob.tbl_end_col_no
  AND nb.hdr_bgn_row_no = ob.hdr_bgn_row_no AND nb.hdr_end_row_no = ob.hdr_end_row_no AND nb.data_bgn_row_no = ob.data_bgn_row_no
  AND nb.row_add_psbl_yn = ob.row_add_psbl_yn AND nb.col_add_psbl_yn = ob.col_add_psbl_yn AND nb.inpt_tbl_expn <=> ob.inpt_tbl_expn)
SELECT p.role, p.sheet, p.name, JSON_EXTRACT(p.new_qry, '$.capabilities') AS capabilities,
       (SELECT COUNT(*) FROM tmd_mdl_inptmodscopd m WHERE m.inpt_tbl_id = p.new_id) AS scopes
FROM p WHERE CAST(p.new_qry AS JSON) <> CAST(p.old_qry AS JSON) ORDER BY p.role, p.sheet, p.name;

ROLLBACK;
-- Replace the ROLLBACK above with COMMIT only after an authorized review of VERIFIED_UNPUBLISHED in this connection.
-- After COMMIT, PART A is intentionally not rerunnable (version/marker guard). Do not delete a committed version
-- automatically; a wrong DRAFT that nothing references is reviewed and handled separately.

-- =====================================================================================================
-- PART B. Publish the committed new version (run separately, after PART A COMMIT and server readiness check)
-- =====================================================================================================
-- Preconditions outside SQL: the server build contains the InputWorkbookPolicy/editor used by the Java verification,
-- mi.model-input.change-worker.enabled=true is planned, uploads/draft workers are stopped during this transaction.
-- Effect: template7 becomes DEPRECATED (definitions, aply_bgn_dtm and Case links unchanged; existing Case drafts keep
-- reading it), the new version becomes the single ACTIVE of DRAFT_C_STRUCTURE (new uploads bind to it).
SET @v_schema = 'midb', @v_actor = 'SYSTEM', @v_version = 2;-- same schema/new version as PART A, audit login
SET @v_source = 7, @v_model = 'DRAFT_C_STRUCTURE';
SET @v_marker = 'editor-write-20261021-png-delete; source=tmplt7/DRAFT_C_STRUCTURE/v1; patched=52/92; scopes=126; NOT_PUBLISHED';
SET @v_ok = 0, @v_published = 0, @v_new = NULL, @v_source_time = NULL, @v_time = NULL;
SET TRANSACTION ISOLATION LEVEL SERIALIZABLE;
START TRANSACTION;
SELECT tmplt_id, tmplt_ver_no, tmplt_stat_cd, aply_bgn_dtm FROM tmd_mdl_inpttmpltm WHERE mdl_spt_cd = @v_model FOR UPDATE;
SET @v_new = (SELECT tmplt_id FROM tmd_mdl_inpttmpltm WHERE BINARY mdl_spt_cd = BINARY @v_model AND tmplt_ver_no = @v_version
  AND BINARY LEFT(tmplt_expn, CHAR_LENGTH(@v_marker) + 9) = BINARY CONCAT(@v_marker, '; digest=')
  AND tmplt_stat_cd = 'DRAFT' AND aply_bgn_dtm IS NULL AND del_yn = 'N');
SELECT case_id FROM tmd_mdl_scnrcasetmpltd WHERE tmplt_id IN (@v_source, @v_new) FOR SHARE;
SET @v_source_time = (SELECT aply_bgn_dtm FROM tmd_mdl_inpttmpltm WHERE tmplt_id = @v_source);
SET @v_links_before = (SELECT COUNT(*) FROM tmd_mdl_scnrcasetmpltd WHERE tmplt_id = @v_source);
SET SESSION group_concat_max_len = 16777216;
SELECT f.inpt_file_id FROM tmd_mdl_inptfiled f WHERE f.tmplt_id = @v_new FOR SHARE;
SELECT s.inpt_sht_id FROM tmd_mdl_inptshtd s JOIN tmd_mdl_inptfiled f USING(inpt_file_id)
 WHERE f.tmplt_id = @v_new FOR SHARE;
SELECT b.inpt_tbl_id FROM tmd_mdl_inpttbld b JOIN tmd_mdl_inptshtd s USING(inpt_sht_id)
 JOIN tmd_mdl_inptfiled f USING(inpt_file_id) WHERE f.tmplt_id = @v_new FOR SHARE;
SELECT m.mod_scop_id FROM tmd_mdl_inptmodscopd m JOIN tmd_mdl_inpttbld b USING(inpt_tbl_id)
 JOIN tmd_mdl_inptshtd s USING(inpt_sht_id) JOIN tmd_mdl_inptfiled f USING(inpt_file_id)
 WHERE f.tmplt_id = @v_new FOR SHARE;
-- The digest binds the exact stored file/sheet/table/scope hierarchy to this DRAFT.
SET @v_catalog_digest = (
  SELECT SHA2(GROUP_CONCAT(SHA2(payload, 256) ORDER BY record_kind, record_id SEPARATOR ','), 256)
  FROM (
    SELECT 'F' AS record_kind, f.inpt_file_id AS record_id,
      CAST(JSON_ARRAY('F', f.inpt_file_id, f.tmplt_id, f.mdl_file_cd, f.file_nm, f.file_ord,
        f.file_type_cd, f.file_strt_hash_val, f.del_yn) AS CHAR) AS payload
    FROM tmd_mdl_inptfiled f WHERE f.tmplt_id = @v_new
    UNION ALL
    SELECT 'S', s.inpt_sht_id,
      CAST(JSON_ARRAY('S', s.inpt_sht_id, s.inpt_file_id, s.sht_nm, s.sht_ord, s.sht_stat_cd, s.del_yn) AS CHAR)
    FROM tmd_mdl_inptshtd s JOIN tmd_mdl_inptfiled f USING(inpt_file_id) WHERE f.tmplt_id = @v_new
    UNION ALL
    SELECT 'T', b.inpt_tbl_id,
      CAST(JSON_ARRAY('T', b.inpt_tbl_id, b.inpt_sht_id, b.inpt_tbl_nm, b.tbl_ord,
        b.tbl_bgn_row_no, b.tbl_end_row_no, b.tbl_bgn_col_no, b.tbl_end_col_no,
        b.hdr_bgn_row_no, b.hdr_end_row_no, b.data_bgn_row_no, b.row_add_psbl_yn,
        b.col_add_psbl_yn, b.inpt_tbl_expn, b.qry_json, b.del_yn) AS CHAR)
    FROM tmd_mdl_inpttbld b JOIN tmd_mdl_inptshtd s USING(inpt_sht_id)
      JOIN tmd_mdl_inptfiled f USING(inpt_file_id) WHERE f.tmplt_id = @v_new
    UNION ALL
    SELECT 'M', m.mod_scop_id,
      CAST(JSON_ARRAY('M', m.mod_scop_id, m.inpt_tbl_id, m.mod_scop_ord, m.bgn_row_no,
        m.end_row_no, m.bgn_col_no, m.end_col_no, m.del_yn) AS CHAR)
    FROM tmd_mdl_inptmodscopd m JOIN tmd_mdl_inpttbld b USING(inpt_tbl_id)
      JOIN tmd_mdl_inptshtd s USING(inpt_sht_id) JOIN tmd_mdl_inptfiled f USING(inpt_file_id)
    WHERE f.tmplt_id = @v_new
  ) hierarchy
);
SET @v_ok = IF(BINARY DATABASE() = BINARY @v_schema AND @@SESSION.foreign_key_checks = 1
 AND @v_catalog_digest IS NOT NULL
 AND (SELECT COUNT(*) FROM tmd_mdl_inpttmpltm WHERE tmplt_id = @v_new
      AND BINARY tmplt_expn = BINARY CONCAT(@v_marker, '; digest=', @v_catalog_digest)) = 1
 AND CHAR_LENGTH(TRIM(@v_actor)) BETWEEN 1 AND 50 AND @v_new IS NOT NULL
 AND (SELECT COUNT(*) FROM tmd_mdl_inpttmpltm WHERE tmplt_id = @v_source AND BINARY mdl_spt_cd = BINARY @v_model
      AND tmplt_ver_no = 1 AND tmplt_stat_cd = 'ACTIVE' AND aply_bgn_dtm IS NOT NULL AND del_yn = 'N') = 1
 AND (SELECT COUNT(*) FROM tmd_mdl_inpttmpltm WHERE mdl_spt_cd = @v_model AND tmplt_stat_cd = 'ACTIVE' AND del_yn = 'N') = 1
 AND NOT EXISTS (SELECT 1 FROM tmd_mdl_scnrcasetmpltd WHERE tmplt_id = @v_new)
 AND NOT EXISTS (SELECT 1 FROM tmd_mdl_inptdrftm WHERE tmplt_id = @v_new)
 AND (SELECT COUNT(*) FROM tmd_mdl_inptfiled WHERE tmplt_id = @v_new AND del_yn = 'N') = 4
 AND (SELECT COUNT(*) FROM tmd_mdl_inptshtd s JOIN tmd_mdl_inptfiled f USING(inpt_file_id) WHERE f.tmplt_id = @v_new AND s.del_yn = 'N') = 70
 AND (SELECT COUNT(*) FROM tmd_mdl_inpttbld b JOIN tmd_mdl_inptshtd s USING(inpt_sht_id) JOIN tmd_mdl_inptfiled f USING(inpt_file_id)
      WHERE f.tmplt_id = @v_new AND b.del_yn = 'N') = 92
 AND (SELECT COUNT(*) FROM tmd_mdl_inpttbld b JOIN tmd_mdl_inptshtd s USING(inpt_sht_id) JOIN tmd_mdl_inptfiled f USING(inpt_file_id)
      WHERE f.tmplt_id = @v_new AND JSON_UNQUOTE(JSON_EXTRACT(b.qry_json, '$.capabilities.SET')) = 'READY') = 52
 AND (SELECT COUNT(*) FROM tmd_mdl_inptmodscopd m JOIN tmd_mdl_inpttbld b USING(inpt_tbl_id) JOIN tmd_mdl_inptshtd s USING(inpt_sht_id)
      JOIN tmd_mdl_inptfiled f USING(inpt_file_id) WHERE f.tmplt_id = @v_new AND m.del_yn = 'N') = 126, 1, 0);
SELECT @v_new AS new_tmplt_id, @v_links_before AS template7_case_links,
       IF(@v_ok = 1, 'PRECHECK_OK', 'STOP_AND_ROLLBACK') AS decision;
-- Order matters for the ACTIVE unique key (actv_mdl_spt_cd): deprecate template7 first, then activate the new root.
SET @v_time = CURRENT_TIMESTAMP(6);
UPDATE tmd_mdl_inpttmpltm SET tmplt_stat_cd = 'DEPRECATED', mod_usr_logn_id = @v_actor, mod_dtm = CURRENT_TIMESTAMP
WHERE @v_ok = 1 AND tmplt_id = @v_source AND tmplt_stat_cd = 'ACTIVE' AND del_yn = 'N';
UPDATE tmd_mdl_inpttmpltm SET tmplt_stat_cd = 'ACTIVE', aply_bgn_dtm = @v_time, mod_usr_logn_id = @v_actor, mod_dtm = CURRENT_TIMESTAMP
WHERE @v_ok = 1 AND tmplt_id = @v_new AND tmplt_stat_cd = 'DRAFT' AND aply_bgn_dtm IS NULL AND del_yn = 'N';
SET @v_published = IF(@v_ok = 1
 AND (SELECT COUNT(*) FROM tmd_mdl_inpttmpltm WHERE tmplt_id = @v_new AND tmplt_stat_cd = 'ACTIVE' AND aply_bgn_dtm = @v_time
      AND BINARY mod_usr_logn_id = BINARY @v_actor AND del_yn = 'N') = 1
 AND (SELECT COUNT(*) FROM tmd_mdl_inpttmpltm WHERE tmplt_id = @v_source AND tmplt_stat_cd = 'DEPRECATED'
      AND aply_bgn_dtm <=> @v_source_time AND del_yn = 'N') = 1
 AND (SELECT COUNT(*) FROM tmd_mdl_inpttmpltm WHERE mdl_spt_cd = @v_model AND tmplt_stat_cd = 'ACTIVE' AND del_yn = 'N') = 1
 AND (SELECT COUNT(*) FROM tmd_mdl_scnrcasetmpltd WHERE tmplt_id = @v_source) = @v_links_before
 AND NOT EXISTS (SELECT 1 FROM tmd_mdl_scnrcasetmpltd WHERE tmplt_id = @v_new), 1, 0);
SELECT tmplt_id, tmplt_ver_no, tmplt_stat_cd, aply_bgn_dtm, del_yn FROM tmd_mdl_inpttmpltm WHERE mdl_spt_cd = @v_model ORDER BY tmplt_ver_no;
SELECT IF(@v_published = 1, 'PUBLISHED_PENDING_COMMIT', 'STOP_AND_ROLLBACK') AS decision;
ROLLBACK;
-- Replace the ROLLBACK above with COMMIT only when PUBLISHED_PENDING_COMMIT. After COMMIT, never switch either root back
-- to DRAFT or edit ACTIVE/DEPRECATED JSON. A problem after publication is fixed by another new version.
-- Smoke after COMMIT (outside SQL): new upload -> draft -> table-data GET shows READY only for the 52 tables;
-- an existing Case on template7 still shows INCOMPLETE (expected; no re-linking here).
